<script setup>
import { computed, ref, watch, onUnmounted } from 'vue'
import { Plus, Search, CalendarDays, GripVertical, LockKeyhole, ArrowUp, ArrowDown, SlidersHorizontal } from 'lucide-vue-next'
import { useWorkboard } from '../stores/workboard'
import InfoTooltip from './InfoTooltip.vue'
const props=defineProps({ sprint:[Number,String] })
const emit=defineEmits(['open-task','new-task','new-column','settings'])
const store=useWorkboard(),search=ref(''),sprintFilter=ref(props.sprint ?? 'all'),assignee=ref('all'),priority=ref('all'),label=ref('all'),blocked=ref('all'),due=ref('all'),filtersOpen=ref(false)
const priorities={low:'Baixa',medium:'Média',high:'Alta'}
const allTasks=computed(()=>store.board.columns.flatMap(c=>c.tasks))
const total=computed(()=>store.board.columns.reduce((n,c)=>n+c.task_count,0))
const finished=computed(()=>store.board.columns.filter(c=>c.kind==='done').reduce((n,c)=>n+c.task_count,0))
function today() {const date=new Date();return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`}
function blockers(task) {return {length:task.dependency_pending ?? 0}}
function visible(col) {return col.tasks}
function count(col) {return col.task_count}
let filterTimer
async function refreshFilters() {if(store.busy){filterTimer=setTimeout(refreshFilters,100);return}try{await store.applyFilters({search:search.value,sprint:sprintFilter.value,assignee:assignee.value,priority:priority.value,label:label.value,blocked:blocked.value,due:due.value})}catch(e){store.error=e.message}}
watch([search,sprintFilter,assignee,priority,label,blocked,due],()=>{clearTimeout(filterTimer);filterTimer=setTimeout(refreshFilters,250)},{immediate:true})
onUnmounted(()=>clearTimeout(filterTimer))
function newTask(col) {const sprint=typeof sprintFilter.value==='number' && store.board.sprints.some(s=>s.id===sprintFilter.value && s.status!=='completed')?sprintFilter.value:null;emit('new-task',col,sprint)}
function drag(event,task) {event.dataTransfer?.setData('text/plain',JSON.stringify({id:task.id,revision:store.board.revision}));if(event.dataTransfer)event.dataTransfer.effectAllowed='move'}
async function drop(event,column,before=null) {try{const data=JSON.parse(event.dataTransfer?.getData('text/plain') || '{}');if(data.id===before)return;if(!allTasks.value.some(t=>t.id===data.id))return;await store.run(()=>store.mutate(`tasks/${data.id}/move/`,'POST',{column,before},data.revision))}catch{store.error='Não foi possível mover o cartão.'}}
async function reorder(task,col,direction) {const list=col.tasks.filter(t=>!t.archived),index=list.findIndex(t=>t.id===task.id);if(direction<0 && index===0 || direction>0 && index===list.length-1)return;const before=direction<0?list[index-1]?.id:list[index+2]?.id ?? null;await store.run(()=>store.mutate(`tasks/${task.id}/move/`,'POST',{column:col.id,before}))}
function resetFilters() {assignee.value='all';priority.value='all';label.value='all';blocked.value='all';due.value='all';search.value='';sprintFilter.value='all'}
function date(value) {return new Date(`${value}T12:00:00`).toLocaleDateString('pt-BR',{day:'2-digit',month:'short'})}
</script>
<template><div class="kanban-controls"><div class="toolbar-right"><select v-model="sprintFilter" class="sprint-filter" aria-label="Filtrar por sprint"><option value="all">Todas as tarefas</option><option value="backlog">Backlog</option><option v-for="s in store.board.sprints" :key="s.id" :value="s.id">{{s.title}}</option></select><span class="progress-text">{{finished}} de {{total}} concluídas</span><label class="search"><Search :size="17"/><input v-model="search" aria-label="Buscar tarefas" placeholder="Buscar tarefas..."></label><button class="secondary" @click="filtersOpen=!filtersOpen"><SlidersHorizontal :size="15"/> Filtros</button></div></div><div v-if="filtersOpen" class="advanced-filters"><label>Responsável<select v-model="assignee" aria-label="Filtrar responsável"><option value="all">Todos</option><option value="none">Sem responsável</option><option v-for="m in store.board.members" :key="m.user" :value="m.user">{{m.user_name}}</option></select></label><label>Prioridade<select v-model="priority" aria-label="Filtrar prioridade"><option value="all">Todas</option><option value="high">Alta</option><option value="medium">Média</option><option value="low">Baixa</option></select></label><label>Etiqueta<select v-model="label" aria-label="Filtrar etiqueta"><option value="all">Todas</option><option v-for="l in store.board.labels" :key="l.id" :value="l.id">{{l.title}}</option></select></label><label>Bloqueio<select v-model="blocked" aria-label="Filtrar bloqueio"><option value="all">Todas as tarefas</option><option value="blocked">Bloqueadas</option><option value="free">Sem bloqueio</option></select></label><label>Prazo<select v-model="due" aria-label="Filtrar prazo"><option value="all">Todos</option><option value="overdue">Atrasadas</option><option value="soon">Próximos 7 dias</option><option value="none">Sem prazo</option></select></label><button class="text-button" @click="resetFilters">Limpar filtros</button></div>
<div class="kanban"><section v-for="(col,i) in store.board.columns" :key="col.id" class="column" :class="{'wip-full':col.wip_limit && count(col)>=col.wip_limit}" @dragover.prevent @drop.prevent="drop($event,col.id)"><div class="column-heading"><div><span class="status-dot" :class="`status-${i%3}`"></span><h2>{{col.title}}</h2><span class="count" :title="`Total de tarefas ativas: ${count(col)}`">{{count(col)}}{{col.wip_limit?` / ${col.wip_limit}`:''}}</span><InfoTooltip label="O que significa WIP?" text="WIP significa Work in Progress (trabalho em andamento). É o limite de tarefas simultâneas na coluna. Exemplo: com limite 3, uma quarta tarefa só entra quando uma das três sair. Deixe vazio para não limitar."/></div><button v-if="store.canWrite" :aria-label="`Adicionar tarefa em ${col.title}`" @click="newTask(col.id)"><Plus :size="18"/></button></div><span v-if="col.wip_limit && count(col)>=col.wip_limit" class="wip-warning">Limite WIP atingido</span><article v-for="task in visible(col)" :key="task.id" class="task" :class="{'task-blocked':task.blocked || blockers(task).length}" :draggable="store.canWrite && !store.busy" @dragstart="drag($event,task)" @dragover.stop.prevent @drop.stop.prevent="drop($event,col.id,task.id)" @click="emit('open-task',task)"><div class="task-top"><span class="priority" :class="task.priority">{{priorities[task.priority]}}</span><GripVertical :size="15"/></div><button class="task-open" @click.stop="emit('open-task',task)"><h3>{{task.title}}</h3></button><span v-if="task.sprint" class="task-sprint">{{store.board.sprints.find(s=>s.id===task.sprint)?.title}}</span><div class="card-labels"><span v-for="id in task.labels" :key="id" class="label-chip" :style="{'--label-color':store.board.labels.find(l=>l.id===id)?.color}">{{store.board.labels.find(l=>l.id===id)?.title}}</span></div><p v-if="task.description">{{task.description}}</p><div v-if="task.blocked || blockers(task).length" class="blocked-message"><LockKeyhole :size="13"/><span>{{task.blocked?task.blocked_reason:`Aguardando ${blockers(task).length} dependência(s)`}}</span></div><div v-if="task.checklist_count" class="checklist-progress">Checklist · {{task.checklist_done}}/{{task.checklist_count}}</div><div class="task-bottom"><span v-if="task.due_date" :class="{overdue:task.due_date<today() && col.kind!=='done'}"><CalendarDays :size="14"/>{{date(task.due_date)}}</span><span v-else>Sem prazo</span><span v-if="task.assignee_name" class="assignee-chip">{{task.assignee_name}}</span><span class="task-id">#{{String(task.id).padStart(3,'0')}}</span></div><div v-if="store.canWrite" class="card-order"><button :disabled="store.busy" :aria-label="`Subir ${task.title}`" @click.stop="reorder(task,col,-1)"><ArrowUp :size="13"/></button><button :disabled="store.busy" :aria-label="`Descer ${task.title}`" @click.stop="reorder(task,col,1)"><ArrowDown :size="13"/></button></div></article><div v-if="!visible(col).length" class="column-empty">Nenhuma tarefa nesta visualização.</div><button v-if="col.next" class="add-task" :disabled="store.busy" @click="store.moreTasks(col)">Carregar mais tarefas ({{col.tasks.length}} / {{col.filtered_count}})</button><button v-if="store.canWrite" class="add-task" @click="newTask(col.id)"><Plus :size="16"/> Adicionar tarefa</button></section><button v-if="store.canManage && store.canWrite" class="add-column" @click="emit('new-column')"><Plus :size="17"/> Nova coluna</button></div></template>
